import type { RichArticle } from './article-data';

type Override = Pick<RichArticle, 'directAnswer' | 'takeaways' | 'taskRows' | 'sections' | 'scripts' | 'faqs' | 'sources'>;

// These are deliberately written as article records rather than produced by a
// substitution template. The shared page layout is presentation only.
export const august17ArticleOverrides: Record<string, Override> = {
  'philippines-hr-after-hours-inbox-escalation': {
    directAnswer: ['An after-hours HR inbox needs a severity rule, an on-call owner, and a record of what was handed over. A Philippines-based coordinator can label the message, preserve the original wording, and notify the named owner. The coordinator should not decide whether a matter is an emergency.', 'The handoff should say what arrived, when it arrived, who can see it, what response is approved, and when the owner must act. Messages about safety, threats, discrimination, pay, medical information, or an active dispute should bypass routine queue handling.'],
    takeaways: ['Define urgent before the inbox receives live work.', 'Keep the original message and limit queue visibility.', 'Give every escalation a named owner and response time.', 'Use approved acknowledgement copy only.', 'Review missed after-hours handoffs with the HR owner.'],
    taskRows: [
      { lane: 'Severity label', philippinesTeam: 'Apply the approved label from the message facts.', owner: 'Set the severity rule and decide whether it is urgent.', check: 'Label points to a written rule' },
      { lane: 'Acknowledgement', philippinesTeam: 'Send the approved receipt message and record the time.', owner: 'Approve any substantive reply or promise.', check: 'Copy and recipient are retained' },
      { lane: 'Escalation', philippinesTeam: 'Notify the named on-call owner through the approved channel.', owner: 'Take the case and record the next action.', check: 'Owner, time, and channel are visible' },
      { lane: 'Morning review', philippinesTeam: 'List unresolved messages and missed response targets.', owner: 'Review the rule and handle sensitive content.', check: 'No item closes without owner confirmation' }
    ],
    sections: [
      { heading: 'Start with a message severity rule', paragraphs: ['“Urgent” should describe an action the company must take quickly, not a sender who writes in capital letters or sends repeated follow-ups. Write examples for payroll cutoffs, safety concerns, access problems, employee complaints, and ordinary status questions.', 'The rule should also say what the coordinator must not infer. A short message mentioning a health issue may need restricted routing even when it does not explain the situation.'] },
      { heading: 'Protect the first handoff', paragraphs: ['Keep the original message unchanged and record the receipt time. The coordinator can remove unnecessary recipients from a broad queue, but should not rewrite a sensitive account into a summary that loses the employee’s wording.', 'Use a separate restricted route for complaints, threats, medical details, and suspected misconduct. The queue should reveal only the status needed for handoff, such as “owner notified” or “awaiting HR review.”'] },
      { heading: 'Make the on-call owner reachable', paragraphs: ['An escalation rule fails if it names a person who is unavailable or a channel no one checks. Record the primary owner, backup owner, permitted contact method, and response target. The coordinator follows the plan and flags a failed delivery.', 'Do not let the coordinator improvise a new emergency contact or promise a resolution time. The employer decides who may receive the message and what the employee may be told.'] },
      { heading: 'Audit the quiet failures', paragraphs: ['Review late-night messages that were marked routine, routed twice, or left without confirmation. Compare the label with the written rule and record one correction for the next review.', 'The useful measure is not a low escalation count. It is whether the right owner saw the message with enough context and whether the queue avoided exposing details to people who did not need them.'] },
      { heading: 'Test four redacted examples', paragraphs: ['Before expanding coverage, walk through a payroll deadline question, a system-access concern, a complaint, and an ordinary policy link request. For each, write the allowed coordinator action and the exact stop point.', 'Ask the HR owner to approve the examples. They become training boundaries, not a substitute for judgment in a live matter.'] }
    ],
    scripts: [{ label: 'Acknowledgement', text: 'We received your message and sent it to the designated HR owner. We will not make a decision in this inbox.' }, { label: 'Escalation note', text: 'Received at [time]. The message concerns [approved category]. The original is attached. Owner notified at [time] through [channel].' }],
    faqs: [{ question: 'Who decides whether a message is urgent?', answer: 'The company HR owner defines and reviews the rule. The coordinator applies the documented categories and escalates uncertainty.' }, { question: 'Can the coordinator answer after hours?', answer: 'Only with approved factual copy. Sensitive questions and decisions go to the named owner.' }, { question: 'What belongs in the queue?', answer: 'The minimum routing data: category, receipt time, visibility level, owner, and status. Keep case detail in the approved restricted system.' }, { question: 'How should missed handoffs be handled?', answer: 'Record the miss, notify the backup owner, and have HR revise the rule or coverage plan.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act resources', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Use the regulator’s privacy principles when limiting access to employee messages.' }]
  },
  'philippines-hr-start-date-change-coordination': {
    directAnswer: ['A start-date change process should separate the approved decision from the administrative updates that follow it. A Philippines-based coordinator can compare the old and new dates, list affected calendars and checklists, and route confirmations. The hiring manager or HR owner keeps control of the decision and message.', 'Treat the new date as proposed until the authorized owner confirms it. Record the source request, approval, effective date, people notified, and systems updated so an old calendar invite does not become the accidental source of truth.'],
    takeaways: ['Require an approved source for every date change.', 'Show old date, proposed date, and confirmed date separately.', 'List each dependent owner before sending updates.', 'Keep candidate and manager messages approved.', 'Close only after downstream records acknowledge the change.'],
    taskRows: [
      { lane: 'Request capture', philippinesTeam: 'Record the request, source, requested date, and affected hire.', owner: 'Approve or reject the change.', check: 'Decision owner is named' },
      { lane: 'Dependency scan', philippinesTeam: 'List interviews, onboarding, equipment, payroll, and access dependencies.', owner: 'Choose which dependencies must move.', check: 'Each dependency has a responsible owner' },
      { lane: 'Communication', philippinesTeam: 'Prepare approved notices and track delivery.', owner: 'Approve wording and recipient list.', check: 'Sent version matches approval' },
      { lane: 'Reconciliation', philippinesTeam: 'Compare calendars and records after the change.', owner: 'Confirm the new date is authoritative.', check: 'Old date is not active in a downstream system' }
    ],
    sections: [
      { heading: 'Keep proposed and confirmed dates apart', paragraphs: ['A manager message may suggest a change before the employer approves it. Use separate fields for requested date, approved date, and date entered into a system. This prevents a tentative conversation from moving onboarding work prematurely.', 'The coordinator can surface a mismatch, but should not decide that a reply, calendar event, or system field counts as approval. The named owner makes the date authoritative.'] },
      { heading: 'Map the dependency chain', paragraphs: ['A start date can affect welcome messages, equipment requests, access tickets, orientation sessions, payroll inputs, and the manager’s first-week plan. List those dependencies from the approved onboarding record rather than relying on memory.', 'Give each dependency an owner and a due point. If one cannot move, record the exception for the manager instead of quietly leaving the old commitment in place.'] },
      { heading: 'Send one approved explanation', paragraphs: ['Candidates and managers should not receive conflicting dates from separate calendars. Prepare the approved message once, record who approved it, and track delivery. The coordinator may answer where to find the updated schedule, but should not explain an employment decision without approved wording.', 'If the change raises a pay, visa, leave, or contract question, route it to the qualified owner. The date tracker is not an advice channel.'] },
      { heading: 'Reconcile after the update', paragraphs: ['Compare the new date against the applicant record, onboarding checklist, calendar, equipment ticket, and access request. Mark each as confirmed, waiting, or exception. A saved field without an acknowledgement is not proof that the dependency moved.', 'Keep the previous date in the audit history when the system supports it. That history explains why reminders or notices changed and helps the owner correct duplicate work.'] },
      { heading: 'Use a change test before launch', paragraphs: ['Run an ordinary one-day shift and a change received after the onboarding checklist was issued. Ask who approves, what gets paused, which messages need replacement, and what closes the request.', 'The test is complete when another coordinator can follow the record without asking which date was merely discussed.'] }
    ],
    scripts: [{ label: 'Approval request', text: 'The requested start date is [old] to [new]. These dependencies are affected: [list]. Please confirm the authoritative date and approved message.' }, { label: 'Reconciliation note', text: 'Confirmed date: [date]. Updated: [records]. Waiting: [items]. Exception owner: [name].' }],
    faqs: [{ question: 'Can a coordinator approve a start-date change?', answer: 'No. The hiring or HR owner approves it and controls the employment message.' }, { question: 'What records should be checked?', answer: 'The approved hiring record, onboarding checklist, calendars, access, equipment, and any payroll input affected by the date.' }, { question: 'What if one dependency cannot move?', answer: 'Record the conflict and route it to its owner. Do not hide it by changing an unrelated date.' }, { question: 'When is the change complete?', answer: 'When the authorized date is recorded, approved communications are delivered, and each dependent owner confirms the update.' }],
    sources: [{ name: 'International Labour Organization: Recruitment and placement', url: 'https://www.ilo.org/topics/recruitment-and-placement', note: 'Provides context for transparent recruitment and clear communication around hiring arrangements.' }]
  },
  'philippines-hr-payroll-cutoff-calendar-support': {
    directAnswer: ['A payroll cutoff calendar is an administrative control, not a payroll approval. A Philippines-based coordinator can list pay-period dates, collect approved inputs, flag missing records, and show which owner still needs to act. Payroll and HR leaders decide what counts, how corrections are handled, and when pay data is released.', 'Use the calendar to distinguish a deadline from a completed input. Every item needs its source, employee or group scope, owner, status, and exception path. Never let a reminder or spreadsheet formula become an unreviewed pay decision.'],
    takeaways: ['Publish cutoffs with a timezone and named owner.', 'Separate received, checked, approved, and submitted states.', 'Keep pay and employee data access narrow.', 'Route corrections instead of overwriting history.', 'Reconcile the calendar against the payroll provider’s record.'],
    taskRows: [
      { lane: 'Calendar setup', philippinesTeam: 'Record pay period, cutoff, timezone, and source.', owner: 'Approve the calendar and responsible payroll owner.', check: 'Date has an authoritative source' },
      { lane: 'Input tracking', philippinesTeam: 'Mark approved inputs received and list missing items.', owner: 'Decide whether an input is valid and complete.', check: 'No blank item is treated as zero' },
      { lane: 'Exception route', philippinesTeam: 'Attach the source and notify payroll of a mismatch.', owner: 'Approve the correction and its treatment.', check: 'Original and corrected values remain traceable' },
      { lane: 'Closeout', philippinesTeam: 'Reconcile statuses after payroll confirms submission.', owner: 'Confirm final review and retain the record.', check: 'Submission evidence matches the period' }
    ],
    sections: [
      { heading: 'Define the cutoff in operational terms', paragraphs: ['A useful calendar says what is due, who supplies it, which timezone applies, and where the official record lives. “Friday cutoff” is incomplete when managers work across regions or a provider accepts inputs at a different local time.', 'Include the period covered and the action required. A deadline to submit approved overtime is different from a deadline to review a report.'] },
      { heading: 'Use states that protect payroll judgment', paragraphs: ['Track received, prepared, reviewed, approved, submitted, and returned. These states show progress without pretending that a coordinator’s check is payroll approval.', 'If a record is missing, leave it missing and escalate. Filling an empty field with an assumption can change pay and makes the later correction harder to explain.'] },
      { heading: 'Handle corrections as controlled changes', paragraphs: ['When a manager sends a correction, preserve the original request, the reason supplied, the affected period, and the owner who decides. The coordinator can attach evidence and update status after approval.', 'Do not erase a previous value to make the sheet look clean. Payroll owners need to see what changed and whether the provider accepted it before the period closed.'] },
      { heading: 'Restrict access to the calendar and inputs', paragraphs: ['The calendar may be broadly visible, but employee pay details should stay in the approved payroll system or restricted workspace. Give the coordinator the minimum access needed to track status and avoid copying sensitive values into reminders.', 'Review who receives notifications. A calendar alert that includes an employee name or amount can disclose more than the task owner needs.'] },
      { heading: 'Reconcile after each pay run', paragraphs: ['Compare the calendar status with the provider confirmation, returned-item list, and approved correction log. Capture the period and confirmation time so a later review can distinguish a late input from a provider rejection.', 'Use recurring misses to change the owner map or deadline. Do not solve a process problem by asking support staff to approve faster.'] }
    ],
    scripts: [{ label: 'Missing input', text: 'The [period] input for [category] is not recorded by the cutoff. Payroll owner: [name]. Please confirm the approved next step.' }, { label: 'Correction route', text: 'Original source received at [time]. Requested correction: [description]. Evidence attached. Payroll owner approval is still required.' }],
    faqs: [{ question: 'Can support staff approve payroll inputs?', answer: 'No. They can track and route approved inputs. Payroll owners decide validity and correction.' }, { question: 'What is the most useful status field?', answer: 'Separate received, reviewed, approved, submitted, and returned so the calendar does not overstate completion.' }, { question: 'Should employee amounts be copied into the calendar?', answer: 'Usually no. Keep the calendar task-focused and store sensitive details in the approved restricted system.' }, { question: 'How should a late item be recorded?', answer: 'Keep the original due date, receipt time, owner, reason supplied, and final disposition.' }],
    sources: [{ name: 'Bangko Sentral ng Pilipinas: Financial consumer protection', url: 'https://www.bsp.gov.ph/Pages/InclusiveFinance/FinancialConsumerProtectionFramework.aspx', note: 'A named Philippine financial regulator source for careful handling of financial information and accountability.' }]
  },
  'philippines-hr-manager-request-intake-design': {
    directAnswer: ['A manager HR intake should turn an informal request into a reviewable record without turning the intake person into an employment adviser. A Philippines-based coordinator can capture the issue, desired outcome, source record, urgency, and owner. HR decides the policy meaning, employee action, and response.', 'The form works when it asks for facts the manager can supply and stops before it asks support staff to diagnose a case. Use categories that route the request, not labels that imply a conclusion.'],
    takeaways: ['Ask what happened and what outcome is requested.', 'Require a source record and affected scope.', 'Keep sensitive details out of broad queues.', 'Make urgency and owner explicit.', 'Review rejected or rerouted requests for better intake questions.'],
    taskRows: [
      { lane: 'Request facts', philippinesTeam: 'Record the manager’s words, date, source, and requested outcome.', owner: 'Clarify facts and make the HR decision.', check: 'No conclusion is inserted into intake' },
      { lane: 'Category', philippinesTeam: 'Apply the approved routing category.', owner: 'Change category when the case needs qualified review.', check: 'Category maps to a real owner' },
      { lane: 'Access', philippinesTeam: 'Keep restricted content in the approved case location.', owner: 'Set viewers and retention.', check: 'Queue shows only routing data' },
      { lane: 'Handoff', philippinesTeam: 'Send a complete record and track acknowledgement.', owner: 'Accept the case or request missing facts.', check: 'Next action and due time are visible' }
    ],
    sections: [
      { heading: 'Design questions around facts', paragraphs: ['Start with “What happened?”, “When did it happen?”, “Who is affected?”, and “What outcome are you requesting?” These questions produce a usable record without suggesting that the manager has already established a violation or performance conclusion.', 'Add the source, such as a policy version, attendance record, approved schedule, or prior message. A source lets the HR owner inspect the claim instead of relying on an intake summary.'] },
      { heading: 'Separate routing from case analysis', paragraphs: ['The intake can classify a request as attendance, pay, leave, conduct, records, or recruiting if those categories map to owners. It should not label a person as dishonest, insubordinate, unsafe, or noncompliant.', 'If the manager includes a sensitive allegation, move the detailed text to the restricted case route and keep only the minimum queue marker.'] },
      { heading: 'Make urgency explainable', paragraphs: ['Ask for the deadline or immediate risk, not simply a high, medium, or low choice. “Payroll closes tomorrow” is actionable context. “Very urgent” is a preference that still needs review.', 'The HR owner can change priority after seeing the facts. The coordinator records the change and the reason supplied, rather than defending the original label.'] },
      { heading: 'Give managers a useful refusal path', paragraphs: ['An intake should tell a manager what to do when the request is incomplete or sensitive. Return missing facts, link to the approved source, or route directly to the HR owner. Do not encourage a manager to put more personal detail into a broad form.', 'The best intake reduces back-and-forth while preserving the boundary around advice and decisions.'] },
      { heading: 'Review the form as work arrives', paragraphs: ['Sample requests for missing sources, vague outcomes, accidental medical detail, and categories that reach the wrong owner. Change the question or routing rule when the same gap appears repeatedly.', 'Keep the original submitted record and the revised route. That history shows whether the form is improving without rewriting the manager’s request.'] }
    ],
    scripts: [{ label: 'Return for facts', text: 'Please add the date, source record, affected scope, and requested outcome. HR will decide the policy or employment question.' }, { label: 'Sensitive route', text: 'This request includes information that should not remain in the general intake. I have routed it to the designated HR owner.' }],
    faqs: [{ question: 'Should an intake ask whether a policy was violated?', answer: 'It can ask what policy or source the manager is concerned about, but the HR owner should determine interpretation and outcome.' }, { question: 'What if a manager has no source?', answer: 'Record that fact and route the request for review. Do not invent evidence or a conclusion.' }, { question: 'How much detail belongs in the queue?', answer: 'Enough to route and protect the deadline. Keep sensitive narratives in the restricted case system.' }, { question: 'Who owns the final reply?', answer: 'The qualified HR owner or another authorized decision maker, using approved language.' }],
    sources: [{ name: 'Civil Service Commission of the Philippines: Data privacy', url: 'https://www.csc.gov.ph/programs/data-privacy', note: 'Relevant Philippine public-sector guidance for limiting personal information in administrative records.' }]
  },
  'philippines-recruiting-interview-reschedule-control': {
    directAnswer: ['Interview reschedule support is a coordination job: compare availability, preserve the agreed interview format, prepare approved messages, and show who confirmed the replacement time. A Philippines-based coordinator can do that work while recruiters and hiring managers retain candidate evaluation, selection, and exception decisions.', 'A controlled reschedule record prevents the candidate from receiving two times or an unexplained change. It should show the original appointment, requested change, participants, time zone, approval, message sent, and remaining conflict.'],
    takeaways: ['Keep the original appointment in the history.', 'Confirm time zone and panel availability before offering a slot.', 'Use approved candidate-safe wording.', 'Escalate accessibility, accommodation, and sensitive concerns.', 'Close only after candidate and panel confirmations match.'],
    taskRows: [
      { lane: 'Change request', philippinesTeam: 'Record who requested the change and the original slot.', owner: 'Approve the reschedule priority.', check: 'Original appointment is preserved' },
      { lane: 'Availability', philippinesTeam: 'Compare panel calendars and approved scheduling rules.', owner: 'Resolve conflicts that require judgment.', check: 'All required participants confirm' },
      { lane: 'Candidate message', philippinesTeam: 'Send approved wording and track delivery.', owner: 'Approve exception language.', check: 'Candidate receives one clear option' },
      { lane: 'Closeout', philippinesTeam: 'Reconcile calendar, ATS stage, and confirmations.', owner: 'Confirm the interview remains valid.', check: 'New slot matches every record' }
    ],
    sections: [
      { heading: 'Preserve the appointment history', paragraphs: ['Do not overwrite the original interview as soon as someone asks for a change. Keep the original time, requester, reason supplied, and status. Then record the proposed replacement separately.', 'This history helps a recruiter explain a delay and prevents a canceled event from being mistaken for a candidate withdrawal.'] },
      { heading: 'Check the full panel, not one calendar', paragraphs: ['The replacement slot must work for the required interviewers, the candidate, and the agreed format. Check time zones and buffers, especially when the panel and candidate work in different locations.', 'If the hiring manager wants to drop a required interviewer or change the assessment, route that decision to the recruiter. Calendar support should not silently change the selection process.'] },
      { heading: 'Use candidate-safe communication', paragraphs: ['The message should state the change, offer the approved next step, and give a contact route for questions. Do not invent a reason, imply a hiring outcome, or expose an internal scheduling conflict that the recruiter has not approved.', 'Record the exact sent version and delivery time. If the candidate raises an accommodation, privacy, or fairness concern, stop and route it.'] },
      { heading: 'Handle late changes visibly', paragraphs: ['Mark a change as late when it falls inside the company’s agreed notice window. The coordinator can flag the risk and offer available approved slots, but the recruiter decides whether the process needs a different response.', 'Review repeated late changes by panel, role, or stage. The remedy may be better scheduling rules, not pressure on the coordinator to make faster guesses.'] },
      { heading: 'Run a candidate-safe test', paragraphs: ['Test a panel conflict, a candidate request, a same-day change, and an accessibility question with redacted details. For each case, document who can act and where the coordinator must stop.', 'A good workflow leaves the candidate with one accurate message and the hiring owner with a complete history.'] }
    ],
    scripts: [{ label: 'Candidate notice', text: 'Your interview needs to move from [old time] to [approved option]. Please confirm whether the new time works, or use [approved contact] for another option.' }, { label: 'Internal escalation', text: 'The requested change affects [panel/candidate]. Available approved slots: [list]. Recruiter decision is needed on [open question].' }],
    faqs: [{ question: 'Can a coordinator choose the new interview slot?', answer: 'They can apply approved scheduling rules and present options. The recruiter owns exceptions and process changes.' }, { question: 'Should the reason for a change be shared with the candidate?', answer: 'Only the reason and wording approved by the recruiter.' }, { question: 'What if the candidate raises an accommodation request?', answer: 'Preserve the request and route it to the qualified recruiting or HR owner.' }, { question: 'What proves the reschedule is complete?', answer: 'Matching candidate and panel confirmations, the updated calendar, and a retained approved message.' }],
    sources: [{ name: 'U.S. Equal Employment Opportunity Commission: Pre-employment inquiries', url: 'https://www.eeoc.gov/pre-employment-inquiries-and-interviews', note: 'Named guidance for keeping interview coordination separate from restricted employment inquiries.' }]
  },
  'philippines-hr-employee-name-correction-routing': {
    directAnswer: ['A name-correction request should preserve the employee’s original request, verify the approved source, and route the change to the system owner. A Philippines-based coordinator can check that required evidence is present and track acknowledgements. The coordinator should not decide identity, alter a record on assumption, or circulate a document more widely than necessary.', 'Use a correction record with the current value, requested value, source, verification status, approver, systems affected, and completion evidence. That separates intake from the authorized change.'],
    takeaways: ['Keep the original request unchanged.', 'Use the approved identity source for verification.', 'List every system that may hold the name.', 'Restrict documents and notifications.', 'Reconcile the display name with the authoritative record.'],
    taskRows: [
      { lane: 'Request', philippinesTeam: 'Capture the request and requested spelling exactly.', owner: 'Confirm the acceptable source and approval path.', check: 'Original wording is retained' },
      { lane: 'Verification', philippinesTeam: 'Check whether required evidence is present and route it securely.', owner: 'Verify identity and approve the correction.', check: 'Evidence status is explicit' },
      { lane: 'System map', philippinesTeam: 'List HRIS, payroll, directory, and document dependencies.', owner: 'Authorize each system update.', check: 'No unapproved system is changed' },
      { lane: 'Reconciliation', philippinesTeam: 'Check completion confirmations without copying the document.', owner: 'Confirm the authoritative value.', check: 'Display records agree or have an exception' }
    ],
    sections: [
      { heading: 'Treat the request as sensitive data work', paragraphs: ['A name is not just a display label when it appears in payroll, identity, benefits, access, and employment records. Capture the request in an approved restricted location and avoid placing identity documents into a general task queue.', 'The coordinator can say what evidence is missing from the checklist. A qualified owner decides whether the supplied source is sufficient.'] },
      { heading: 'Map authoritative and dependent systems', paragraphs: ['Start with the record that the employer treats as authoritative, then list systems that copy or display the name. Payroll, email, access, benefits, recruiting, and document templates may have different owners.', 'Do not update a dependent display field first and call the work complete. The system owner should confirm the source correction and downstream sequence.'] },
      { heading: 'Keep correction evidence traceable', paragraphs: ['Record who received the request, what was checked, who approved the change, and when each system confirmed it. Keep the document itself in its approved location and link to it only where access is permitted.', 'A correction log should explain the change without exposing the whole identity document to every person who can see the task status.'] },
      { heading: 'Handle conflicts without guessing', paragraphs: ['If the request, source, and current record do not agree, stop at the conflict. Do not choose the spelling that appears most often or infer that a formatting difference is harmless.', 'Route the mismatch to HR or the records owner and keep the status as pending. A visible exception is safer than a confident but unsupported edit.'] },
      { heading: 'Check the employee-facing result', paragraphs: ['After owners confirm the update, check permitted displays such as the employee portal or directory. Do not use broad test messages that reveal the old and new value to unrelated recipients.', 'Close the task with the system confirmations, approval, and access-limited evidence.'] }
    ],
    scripts: [{ label: 'Missing evidence', text: 'The correction request is recorded. The approved verification source is still missing, so no record has been changed.' }, { label: 'Conflict note', text: 'Current record and submitted source do not match on [field]. Routed to [owner] for verification. Status remains pending.' }],
    faqs: [{ question: 'Can support staff change the HRIS name?', answer: 'Only if the system owner has explicitly authorized that task and the evidence and approval rules are met. Otherwise they route it.' }, { question: 'Should a copy of identity evidence go in the ticket?', answer: 'Only in the approved restricted location, not a broad queue.' }, { question: 'What if payroll and HRIS disagree?', answer: 'Keep both values visible to the authorized owner and route the reconciliation. Do not choose one by assumption.' }, { question: 'What is the final check?', answer: 'The authorized source and permitted downstream displays agree, with confirmations retained.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant privacy principles for purpose, access, and protection of employee identity records.' }]
  },
  'philippines-hr-confidential-case-routing': {
    directAnswer: ['Confidential case routing should expose only what a recipient needs to take the next action. A Philippines-based coordinator can preserve the original intake, assign a restricted case identifier, notify the authorized owner, and track acknowledgement. The coordinator should not summarize allegations, investigate, or decide who is at fault.', 'Design the queue around access boundaries. The broad task view can show case ID, owner, status, and next action while the narrative, documents, and communications remain in a restricted case system.'],
    takeaways: ['Separate routing metadata from case narrative.', 'Use a restricted owner map and backup route.', 'Preserve original wording and receipt time.', 'Do not investigate through the coordination queue.', 'Audit access and closeout, not just response time.'],
    taskRows: [
      { lane: 'Intake', philippinesTeam: 'Record receipt and create the restricted case ID.', owner: 'Decide the case owner and access group.', check: 'Case ID has no unnecessary detail' },
      { lane: 'Notification', philippinesTeam: 'Notify only the authorized owner through the approved channel.', owner: 'Accept the case and set the next action.', check: 'Delivery and acknowledgement are recorded' },
      { lane: 'Status', philippinesTeam: 'Maintain minimal status and due information.', owner: 'Update substantive case status.', check: 'Queue reveals no narrative' },
      { lane: 'Closeout', philippinesTeam: 'Record owner confirmation and approved archive location.', owner: 'Set retention and final disposition.', check: 'Access is removed or narrowed when required' }
    ],
    sections: [
      { heading: 'Build a narrow routing record', paragraphs: ['A general work queue does not need an allegation, diagnosis, or full employee story to show that an owner must act. Use a case ID, sensitivity class, receipt time, owner, backup, and next action.', 'The restricted system holds the narrative and source documents. The coordinator should not copy those details into reminders, reports, or broad chat channels.'] },
      { heading: 'Set access before the first case', paragraphs: ['Name who can receive a confidential case, who covers absence, and which channel is approved. A routing process that waits until an incident arrives will often default to the easiest channel rather than the safest one.', 'Test access with redacted examples. The coordinator needs enough visibility to move the handoff, not enough access to read every case.'] },
      { heading: 'Preserve the employee’s words', paragraphs: ['Do not rewrite a sensitive message into a conclusion. Preserve the original in the approved system and use the case ID when notifying the owner.', 'If the message includes an immediate safety concern or a threat, follow the approved emergency route. The coordinator should not debate credibility or ask probing questions.'] },
      { heading: 'Track acknowledgement without exposing detail', paragraphs: ['“Owner notified” and “owner acknowledged” are useful statuses. “Employee is making a false accusation” is not a routing status and should not appear in the queue.', 'Review who can see status exports and calendar alerts. Metadata can still identify a person or a sensitive situation when combined with other fields.'] },
      { heading: 'Review access after closure', paragraphs: ['At closeout, confirm the owner’s disposition, approved retention location, and any access changes. The coordinator records the control evidence and does not decide whether the case is substantively closed.', 'Periodic access review should look for viewers who no longer need the case, duplicate copies, and notifications that carried too much detail.'] }
    ],
    scripts: [{ label: 'Restricted handoff', text: 'Confidential case [ID] received at [time]. Authorized owner notified through [channel]. Narrative remains in the restricted case location.' }, { label: 'Access stop', text: 'This queue does not contain the case detail. Please use case [ID] in the approved restricted system.' }],
    faqs: [{ question: 'Can the coordinator summarize a confidential complaint?', answer: 'Only to the minimum approved routing metadata. The original and substantive narrative should remain with the authorized owner.' }, { question: 'What does the broad queue show?', answer: 'Case ID, sensitivity marker, owner, status, next action, and due information.' }, { question: 'Who decides retention?', answer: 'The authorized HR or records owner, using the company’s legal and privacy requirements.' }, { question: 'What if the owner is unavailable?', answer: 'Use the named backup route. Do not widen access informally.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant guidance for limiting disclosure and protecting personal information in case handling.' }]
  },
  'philippines-hr-return-to-work-coordination-planning': {
    directAnswer: ['Return-to-work coordination should track approved dates, logistics, and owner checkpoints without asking an administrative support role to interpret medical information or decide accommodations. A Philippines-based coordinator can schedule the approved meeting, list workplace dependencies, and record what the responsible HR owner confirms.', 'Keep medical documents and sensitive explanations in the restricted system. The coordination record should show the approved work arrangement, next owner action, and outstanding logistics, not a medical conclusion.'],
    takeaways: ['Track work steps, not medical judgments.', 'Use approved sources and restricted storage.', 'Name the HR and manager owners.', 'Route accommodation questions to qualified reviewers.', 'Close logistics only after the owner confirms them.'],
    taskRows: [
      { lane: 'Approved plan', philippinesTeam: 'Record the approved return date and logistics.', owner: 'Review medical, accommodation, and employment questions.', check: 'Source and owner are identified' },
      { lane: 'Workplace setup', philippinesTeam: 'Coordinate approved schedule, equipment, and meeting details.', owner: 'Approve the arrangement and exceptions.', check: 'Each dependency has a confirmation' },
      { lane: 'Communication', philippinesTeam: 'Send only approved logistical copy.', owner: 'Handle sensitive employee communication.', check: 'Message contains no unsupported conclusion' },
      { lane: 'Checkpoint', philippinesTeam: 'Schedule the agreed review and record attendance or status.', owner: 'Decide whether the plan changes.', check: 'Next review has an accountable owner' }
    ],
    sections: [
      { heading: 'Keep the record about work logistics', paragraphs: ['A coordinator may need the approved return date, hours, location, equipment, manager, and review date. They do not need a diagnosis or an opinion about whether the employee is ready.', 'Separate the logistics record from medical or accommodation documents. The qualified HR owner controls the latter and decides who may view them.'] },
      { heading: 'Define the decision boundary', paragraphs: ['The manager may approve ordinary scheduling details, while HR or a qualified adviser handles accommodation, fitness, leave, and legal questions. Write those boundaries before the first handoff.', 'When the employee asks for a change or explains a new limitation, preserve the request and route it. Do not promise that a particular arrangement will be granted.'] },
      { heading: 'Coordinate the first day back', paragraphs: ['Confirm the approved start time, location, system access, equipment, manager meeting, and any agreed communication. A checklist makes missing logistics visible without turning the coordinator into a case manager.', 'If a dependency is not ready, report it to the owner and record the impact. Do not change the return date or tell the employee to work around a missing approval.'] },
      { heading: 'Use neutral checkpoint notes', paragraphs: ['A useful note says “manager meeting scheduled,” “equipment confirmed,” or “HR review pending.” It should not say that an employee is medically cleared or unable to perform unless an authorized source and owner have made that determination.', 'Keep the original approved plan and later changes visible to the authorized reviewers.'] },
      { heading: 'Review the boundary after the first case', paragraphs: ['Ask whether the coordinator saw information they did not need, whether an employee question reached the right owner, and whether a manager mistook a logistics status for a decision.', 'Update the checklist and access rules from those observations, without adding medical detail to the routine workflow.'] }
    ],
    scripts: [{ label: 'Logistics message', text: 'Your approved return logistics are [date/time/location]. HR remains the contact for questions about accommodations, leave, or changes.' }, { label: 'Sensitive route', text: 'The employee has asked about [sensitive topic]. I have preserved the request and routed it to the HR owner for review.' }],
    faqs: [{ question: 'Can the coordinator review a medical note?', answer: 'Only if the role and approved system explicitly require it. In ordinary coordination, route medical content to the qualified owner.' }, { question: 'Who changes the return plan?', answer: 'The authorized HR and management owners, with qualified advice where needed.' }, { question: 'What belongs in a status report?', answer: 'Approved logistics, owner, next action, and due date, without unnecessary sensitive detail.' }, { question: 'What proves the first-day plan is ready?', answer: 'The approved schedule and confirmations for each required workplace dependency.' }],
    sources: [{ name: 'U.S. Equal Employment Opportunity Commission: Disability discrimination', url: 'https://www.eeoc.gov/disability-discrimination', note: 'Named reference for keeping accommodation and medical decisions with qualified owners.' }]
  },
  'philippines-hr-benefits-life-event-intake': {
    directAnswer: ['Benefits life-event intake should collect the approved request and required documents, then route eligibility and deadline questions to the plan owner. A Philippines-based coordinator can check completeness, protect the document handoff, and track the response. The coordinator should not decide eligibility or advise an employee on coverage.', 'Separate “document received” from “event accepted” and “enrollment completed.” Those states belong to different owners and prevent a checklist from becoming an accidental benefits determination.'],
    takeaways: ['Use a document checklist tied to the plan source.', 'Keep eligibility separate from receipt.', 'Protect family and identity documents.', 'Record plan deadlines and owner response times.', 'Never treat silence as approval.'],
    taskRows: [
      { lane: 'Intake', philippinesTeam: 'Record event type, receipt date, source, and missing checklist items.', owner: 'Confirm eligibility requirements.', check: 'Receipt is not marked approved' },
      { lane: 'Document route', philippinesTeam: 'Send documents to the approved restricted destination.', owner: 'Review evidence and request clarification.', check: 'No document is left in the general queue' },
      { lane: 'Deadline', philippinesTeam: 'Track plan deadline and reminders.', owner: 'Decide exceptions or late treatment.', check: 'Deadline source is named' },
      { lane: 'Completion', philippinesTeam: 'Record carrier or plan confirmation.', owner: 'Confirm enrollment outcome and employee advice.', check: 'Confirmation matches the event record' }
    ],
    sections: [
      { heading: 'Start with the plan’s own checklist', paragraphs: ['A life-event request may require an event date, relationship information, proof, and a form. The coordinator should use the current approved plan material and identify what is missing without saying whether the event qualifies.', 'The checklist needs a version date. Benefits rules can change, and an old list can create false certainty.'] },
      { heading: 'Separate receipt from eligibility', paragraphs: ['Mark a document received when it arrives, not when an owner accepts it. Then track review, clarification, eligibility, and enrollment as separate states.', 'This distinction matters when a family document is complete but the plan owner still needs to decide whether the event falls within a permitted window.'] },
      { heading: 'Protect the document handoff', paragraphs: ['Family and identity documents should go only to the approved restricted destination. Do not attach them to a broad task email or place them in a shared folder because it is convenient.', 'Record the secure handoff and recipient, not a copy of the document in the tracker.'] },
      { heading: 'Track deadlines without giving advice', paragraphs: ['The coordinator can remind an employee of an approved submission deadline and link to the current plan source. Questions about coverage, tax treatment, eligibility, or a late request go to the plan owner.', 'Never promise that a document will be accepted or that enrollment will backdate. Those outcomes require an authorized decision.'] },
      { heading: 'Close from the plan confirmation', paragraphs: ['A life-event task closes when the authorized plan or carrier owner confirms the outcome and the employee receives approved next steps. A sent reminder is not completion.', 'Keep the event, version, review owner, confirmation, and date in the restricted record.'] }
    ],
    scripts: [{ label: 'Missing document', text: 'We received your life-event request. The current checklist still needs [item]. The plan owner will decide eligibility after review.' }, { label: 'Advice boundary', text: 'I can track the document and deadline. The benefits owner must answer questions about coverage or eligibility.' }],
    faqs: [{ question: 'Can a coordinator decide whether a life event qualifies?', answer: 'No. They can check the approved checklist and route the request.' }, { question: 'What if a deadline has passed?', answer: 'Record the timing and route it to the plan owner. Do not promise an exception.' }, { question: 'Where should documents be stored?', answer: 'In the approved restricted benefits system, not a broad coordination queue.' }, { question: 'When is intake complete?', answer: 'When receipt, review, eligibility, enrollment, and employee communication have their correct owner and status.' }],
    sources: [{ name: 'PhilHealth: Member services', url: 'https://www.philhealth.gov.ph/members/', note: 'A named Philippine health-program source for directing benefit-specific questions to the responsible program.' }]
  },
  'philippines-hr-manager-self-service-catalog': {
    directAnswer: ['A manager self-service catalog should make routine HR requests easy to describe and easy to route. A Philippines-based coordinator can maintain categories, required fields, source links, and owner names. HR owners must approve the catalog, interpret policy, and handle exceptions.', 'The catalog should tell managers what support can prepare, what information to provide, and when to contact HR directly. It is a routing aid, not a library of unsupported employment answers.'],
    takeaways: ['Name the request outcome in plain language.', 'Link each category to a current owner and source.', 'Ask only for facts needed to route.', 'Put sensitive and urgent paths at the top.', 'Review categories that generate repeated clarification.'],
    taskRows: [
      { lane: 'Category design', philippinesTeam: 'Draft labels, examples, and required fields.', owner: 'Approve meaning and scope.', check: 'Every category has an owner' },
      { lane: 'Source links', philippinesTeam: 'Check that links resolve to current approved material.', owner: 'Approve interpretation and exceptions.', check: 'Version or review date is visible' },
      { lane: 'Request route', philippinesTeam: 'Apply the category and track missing information.', owner: 'Accept or redirect the request.', check: 'Route matches the request facts' },
      { lane: 'Catalog review', philippinesTeam: 'Report stale links and ambiguous requests.', owner: 'Change the rule or retire the category.', check: 'Revision has an approver' }
    ],
    sections: [
      { heading: 'Write categories from manager tasks', paragraphs: ['A category such as “change an employee’s schedule” is more useful than “people issue.” Add a short description, the information required, and the action the manager expects.', 'Avoid categories that announce a conclusion, such as “discipline an underperformer.” The owner needs facts and context before deciding what process applies.'] },
      { heading: 'Put boundaries beside the answer', paragraphs: ['A catalog link should state when the manager can use the routine route and when HR must review. Pay, complaints, medical matters, discrimination, investigations, and policy exceptions need a direct owner path.', 'Do not bury the stop rule in a separate policy page. The person submitting the request needs to see it at the decision point.'] },
      { heading: 'Keep sources current', paragraphs: ['Record the source title, owner, review date, and approved link. A coordinator can check that a link works and report a stale version, but should not rewrite policy text to make the catalog easier to read.', 'If a source is under review, mark it as pending and route questions to HR rather than silently leaving an old answer live.'] },
      { heading: 'Use request examples carefully', paragraphs: ['Examples should demonstrate the facts needed for routing without exposing a real employee’s information. Include one ordinary request and one exception for each high-volume category.', 'Review examples when the process changes. An example that no longer matches the approved owner can send a manager to the wrong place.'] },
      { heading: 'Measure usefulness by rework', paragraphs: ['Count repeated clarification, wrong routes, stale links, and requests that should have gone directly to HR. Those signals show where the catalog needs a better question or boundary.', 'Do not optimize for fewer HR escalations by making the catalog answer questions that require qualified judgment.'] }
    ],
    scripts: [{ label: 'Catalog entry', text: 'Use this route for [routine outcome]. Provide [facts]. HR review is required for [exceptions]. Owner: [role/channel].' }, { label: 'Stale source', text: 'The linked source is past its review date. The catalog remains available for routing, but interpretation goes to [owner] until the source is approved.' }],
    faqs: [{ question: 'Who approves a catalog category?', answer: 'The HR owner who owns the process and its interpretation.' }, { question: 'Can a coordinator write policy answers?', answer: 'They can maintain approved wording and links. They should not interpret or change policy.' }, { question: 'What makes a category useful?', answer: 'A plain-language outcome, required facts, source, owner, and exception path.' }, { question: 'How often should it be reviewed?', answer: 'Use the owner’s review cycle and review sooner when links, policies, or recurring misroutes change.' }],
    sources: [{ name: 'International Labour Organization: Human resources management', url: 'https://www.ilo.org/topics/human-resources-management', note: 'Named labour guidance context for clear roles and responsible workplace administration.' }]
  },
  'philippines-hr-policy-exception-evidence-packet': {
    directAnswer: ['An evidence packet for a policy exception should help the authorized HR owner decide without asking the coordinator to decide first. It can contain the request, policy version, relevant records, stated reason, deadline, open questions, and owner. The packet should distinguish supplied facts from assumptions.', 'Keep the current policy text and the request together, but do not expand a narrow exception into a general policy interpretation. The owner decides whether an exception exists and what response is appropriate.'],
    takeaways: ['Freeze the policy version used for review.', 'Separate facts, requests, and open questions.', 'Record the decision owner and deadline.', 'Protect employee detail in the approved location.', 'Preserve the decision and reason supplied.'],
    taskRows: [
      { lane: 'Request', philippinesTeam: 'Capture the requester’s words, date, and desired exception.', owner: 'Decide whether the request is within scope.', check: 'Request is not rewritten as a conclusion' },
      { lane: 'Source pack', philippinesTeam: 'Attach or link the current policy and relevant approved records.', owner: 'Interpret the policy and seek advice.', check: 'Version and source are named' },
      { lane: 'Questions', philippinesTeam: 'List missing facts and route them to the right person.', owner: 'Choose what facts are material.', check: 'Open questions have owners' },
      { lane: 'Decision record', philippinesTeam: 'File the approved outcome and notify the requester with approved copy.', owner: 'Approve outcome, reason, and communication.', check: 'Decision links to packet' }
    ],
    sections: [
      { heading: 'Freeze the source before assembling', paragraphs: ['Policies change. Record the title, version, approval date, and location used for the packet. If the request cites an old version, include that fact rather than silently substituting a newer rule.', 'The coordinator can gather sources and flag a mismatch. HR decides which version governs the request.'] },
      { heading: 'Build facts without advocacy', paragraphs: ['Use a table with request, date, affected process, supplied evidence, missing information, and requested outcome. Keep the requester’s explanation distinct from the coordinator’s routing note.', 'Avoid labels such as “deserved” or “unfair” unless they are clearly quoted and the restricted record permits them. The packet should support a decision, not steer it through adjectives.'] },
      { heading: 'State the boundary of the packet', paragraphs: ['An exception packet does not decide legal risk, accommodation, discrimination, pay, or employee outcome. Those questions need qualified review and may require additional advisers.', 'Put the stop rule in the cover note so the next owner knows which work is complete and which judgment remains open.'] },
      { heading: 'Route questions in a controlled way', paragraphs: ['Every missing fact should have one owner and a due point. A coordinator can ask a manager for an approved record, but should not interview an employee about a sensitive matter unless that role is explicitly assigned and trained.', 'Keep follow-up in the restricted case location when the request includes personal details.'] },
      { heading: 'Close with the approved decision', paragraphs: ['The final packet should show the decision, date, owner, policy version, reason supplied, communication status, and any review date. The coordinator files and routes it; the owner supplies the decision.', 'If the request is declined or remains unresolved, record that status instead of marking the evidence packet complete.'] }
    ],
    scripts: [{ label: 'Packet cover note', text: 'This packet contains the request, policy version, supplied records, and open questions. HR owner decision is still required for [issue].' }, { label: 'Missing fact', text: 'The packet is paused for [fact/source]. No exception decision has been made.' }],
    faqs: [{ question: 'Can a coordinator recommend an exception?', answer: 'They can identify options or missing evidence if the owner requests it, but the authorized HR owner decides.' }, { question: 'What if the policy version is unclear?', answer: 'Record the mismatch and route it to the policy owner.' }, { question: 'Should the packet include every employee detail?', answer: 'No. Include the minimum material information in the approved restricted location.' }, { question: 'What proves the packet is closed?', answer: 'An authorized decision, recorded policy version, approved communication, and any follow-up owner.' }],
    sources: [{ name: 'Department of Labor and Employment Philippines: Labor standards', url: 'https://www.dole.gov.ph/labor-standards/', note: 'Named Philippine labour authority source to consult when an exception touches employment standards.' }]
  },
  'philippines-hr-probation-review-reminders': {
    directAnswer: ['Probation review administration is about timing, evidence collection, and clear ownership. A Philippines-based coordinator can track review dates, remind managers, collect approved forms, and flag missing inputs. The manager and HR owner retain performance judgment, feedback, and the employment decision.', 'A reminder process should never write a conclusion for the manager or imply that a missed form produces an automatic outcome. Track the scheduled review, the approved source, the response, and the next owner action.'],
    takeaways: ['Record the probation start and review dates from an approved source.', 'Send reminders without coaching the conclusion.', 'Keep manager feedback in the approved record.', 'Escalate missed reviews and employee questions.', 'Never convert missing paperwork into a performance result.'],
    taskRows: [
      { lane: 'Date control', philippinesTeam: 'Calculate or record review dates from the approved employment record.', owner: 'Confirm the governing date and review process.', check: 'Date source is visible' },
      { lane: 'Reminder', philippinesTeam: 'Send approved reminders and track delivery.', owner: 'Set review expectations and wording.', check: 'Reminder does not contain a conclusion' },
      { lane: 'Evidence', philippinesTeam: 'Collect completed forms and flag missing sections.', owner: 'Write and approve performance feedback.', check: 'Manager remains the author of judgment' },
      { lane: 'Escalation', philippinesTeam: 'Route late, disputed, or sensitive responses.', owner: 'Handle employee and employment questions.', check: 'Exception has an owner and due date' }
    ],
    sections: [
      { heading: 'Make the review date authoritative', paragraphs: ['A probation reminder is only useful when its date comes from the approved employment record and the company’s current process. Record the source, start date, review date, timezone, and owner.', 'If the contract, HRIS, and manager calendar disagree, flag the mismatch. Do not choose the date that creates the easiest reminder.'] },
      { heading: 'Remind without writing feedback', paragraphs: ['A reminder can list the form, required sections, deadline, and submission route. It should not suggest that the employee is meeting or failing expectations.', 'Managers write their own observations and decisions. Support staff may identify a blank field or return a form for completion, but should not fill in performance language.'] },
      { heading: 'Handle employee questions carefully', paragraphs: ['An employee may ask what the review means, whether the date can move, or what happens next. Use approved factual copy and route questions about rights, pay, status, or a disputed review to HR.', 'Keep the employee’s question and the approved response in the correct record. Do not promise continued employment or an outcome.'] },
      { heading: 'Treat late reviews as exceptions', paragraphs: ['If a manager misses a review date, record the miss and notify the HR owner. A late form should not silently receive a new date that changes the process.', 'The owner decides the next step and whether communication is needed. The coordinator tracks that decision after it is made.'] },
      { heading: 'Review the reminder system', paragraphs: ['Sample reminders for correct dates, recipients, approved wording, and privacy. Check that a manager who changed roles or left the company does not remain the owner.', 'A clean calendar is useful only when the underlying employment record and owner map are current.'] }
    ],
    scripts: [{ label: 'Manager reminder', text: 'The approved probation review for [employee/record ID] is due [date]. Please complete the current form and return it through [approved route].' }, { label: 'Employee escalation', text: 'I have routed your question about the review to the HR owner. I cannot predict or decide the review outcome.' }],
    faqs: [{ question: 'Can a coordinator tell a manager what rating to give?', answer: 'No. The manager supplies performance judgment under the approved process.' }, { question: 'What if the review date is disputed?', answer: 'Preserve the sources and route the dispute to HR.' }, { question: 'Can a missed review be marked failed?', answer: 'No. Missing administration is not a performance conclusion.' }, { question: 'What should the reminder contain?', answer: 'The approved review date, form or source, submission route, owner, and deadline.' }],
    sources: [{ name: 'Department of Labor and Employment Philippines: Labor standards', url: 'https://www.dole.gov.ph/labor-standards/', note: 'Named Philippine labour authority source for directing employment-process questions to qualified owners.' }]
  },
  'philippines-hr-exit-property-custody-log': {
    directAnswer: ['An exit property log tracks custody, return, condition, and exceptions without deciding blame or recovery. A Philippines-based coordinator can send approved instructions, match an asset to the employee record, record handoff evidence, and alert the asset owner. Facilities, IT, HR, and management decide disputed loss, deductions, and next steps.', 'Use one row per asset with an identifier, custodian, expected return, handoff, condition, and open exception. Keep photographs, receipts, and personal details in the approved restricted location.'],
    takeaways: ['Start from the authoritative asset record.', 'Record custody changes, not assumptions.', 'Separate return evidence from condition judgment.', 'Route loss, damage, and deduction questions.', 'Close only with owner confirmation.'],
    taskRows: [
      { lane: 'Asset map', philippinesTeam: 'Match approved asset IDs to the exit record.', owner: 'Confirm the property list and responsible owners.', check: 'No asset is added from guesswork' },
      { lane: 'Return notice', philippinesTeam: 'Send approved instructions and track delivery.', owner: 'Approve timing, location, and exceptions.', check: 'Message and recipient are retained' },
      { lane: 'Handoff', philippinesTeam: 'Record receipt, date, custodian, and source evidence.', owner: 'Inspect condition and decide exception treatment.', check: 'Custody changes have proof' },
      { lane: 'Closeout', philippinesTeam: 'List unresolved property items and next owner.', owner: 'Approve final disposition.', check: 'Open issue is not hidden by closure' }
    ],
    sections: [
      { heading: 'Begin with the asset record', paragraphs: ['Use the asset identifier, assigned custodian, issuing team, and expected return source. Do not add a device because someone remembers seeing it with an employee.', 'If the record is incomplete, flag the gap to IT or facilities. The coordinator can reconcile records, but should not decide ownership from a photograph or message alone.'] },
      { heading: 'Make custody changes visible', paragraphs: ['Record when the asset moved from employee to courier, facilities, IT, or another owner. A signature, receipt, ticket, or approved handoff note can support the change.', 'Separate “received” from “inspected.” The person who receives a laptop may not be the person qualified to assess its condition or data state.'] },
      { heading: 'Handle exceptions without blame', paragraphs: ['A missing device, damage report, or disputed return needs an owner. The coordinator records the facts supplied and routes the issue; they should not accuse the employee or calculate a deduction.', 'Keep personal address and shipping details in the restricted system. The public-facing task status needs only the delivery state and owner.'] },
      { heading: 'Coordinate with access closeout', paragraphs: ['Property return and access shutdown are related but separate controls. A returned laptop does not prove that accounts were disabled, and an account closure does not prove that the device was received.', 'Link the records through approved IDs and owners without copying sensitive content into the property queue.'] },
      { heading: 'Close from the responsible owner', paragraphs: ['The asset owner confirms return, inspection, transfer, loss treatment, or continued investigation. The coordinator files the proof and shows open work.', 'Review recurring gaps such as missing asset IDs, unclear couriers, or unapproved storage. Fix the control rather than asking support staff to infer more.'] }
    ],
    scripts: [{ label: 'Return instruction', text: 'Please return the items listed in the approved notice using [method] by [date]. Questions about loss, damage, or deductions go to [owner].' }, { label: 'Exception note', text: 'Asset [ID] is not yet reconciled. Last approved custody record: [event]. Next owner: [name].' }],
    faqs: [{ question: 'Can the coordinator decide who pays for a missing item?', answer: 'No. The authorized owner decides loss, damage, deduction, and dispute treatment.' }, { question: 'What proves a return?', answer: 'A receipt or approved handoff record that identifies the asset and new custodian.' }, { question: 'Should condition be recorded at receipt?', answer: 'Record the receipt and route inspection to the qualified asset owner.' }, { question: 'Can the property log include personal shipping details?', answer: 'Only in the approved restricted system, not a broad tracker.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant privacy context for limiting personal and device information in operational logs.' }]
  },
  'philippines-hr-employment-verification-routing': {
    directAnswer: ['Employment verification routing should verify the requester, confirm authorization, and use an approved source before any information is released. A Philippines-based coordinator can record the request, route it to the employer’s authorized verifier, and track the response. The coordinator should not decide what the employer may disclose.', 'Keep identity, consent, requested fields, source, approval, and release evidence together in the restricted record. A request that looks routine can still disclose employment or personal information to the wrong recipient.'],
    takeaways: ['Verify requester and employee authorization.', 'Use the approved verification source.', 'Separate preparation from release approval.', 'Record exactly what was disclosed and when.', 'Route unusual or disputed requests to HR or legal.'],
    taskRows: [
      { lane: 'Requester check', philippinesTeam: 'Capture requester identity, organization, purpose, and channel.', owner: 'Decide whether authorization is sufficient.', check: 'Requester is not assumed genuine' },
      { lane: 'Source check', philippinesTeam: 'Locate the approved employment record without broad copying.', owner: 'Confirm permitted fields and wording.', check: 'Source owner is named' },
      { lane: 'Preparation', philippinesTeam: 'Prepare the approved form or draft for review.', owner: 'Approve disclosure and release.', check: 'Draft is not sent automatically' },
      { lane: 'Record', philippinesTeam: 'File consent, approval, sent version, and timestamp.', owner: 'Handle disputes or corrections.', check: 'Disclosure scope is traceable' }
    ],
    sections: [
      { heading: 'Verify the requester before the record', paragraphs: ['An email address, logo, or familiar company name is not enough to establish authority. Use the approved verification method and record the purpose, requested fields, and employee consent when required.', 'If the request is incomplete, the coordinator can ask for the missing authorization. They should not search broadly for personal details to satisfy it.'] },
      { heading: 'Use a narrow disclosure scope', paragraphs: ['The authorized verifier decides whether the request calls for dates, title, status, or another permitted field. Prepare only what the owner approved.', 'Do not add salary, reason for leaving, performance, or personal contact information because a form has a blank field.'] },
      { heading: 'Separate draft from release', paragraphs: ['A coordinator may populate an approved form from an approved source, but the employer’s verifier reviews and releases it. Keep the draft and sent version distinct.', 'The sent record should show recipient, fields disclosed, approval, date, and channel. This helps correct an error without pretending the original was never sent.'] },
      { heading: 'Route unusual requests', paragraphs: ['Requests from debt collectors, law enforcement, former employees, or unknown third parties may need a different owner. Keep the request and route it without making a legal conclusion.', 'If the employee disputes the record, preserve the dispute and send it to HR or records ownership.'] },
      { heading: 'Review the verification trail', paragraphs: ['Sample completed verifications for authorization, source, scope, approval, and delivery. Check whether old forms or personal inboxes are still used.', 'A reliable process reduces disclosure mistakes by making the verifier visible, not by allowing the coordinator to answer faster.'] }
    ],
    scripts: [{ label: 'Authorization request', text: 'Please provide the approved authorization and the specific employment fields requested. The employer verifier must review before release.' }, { label: 'Scope note', text: 'Requested fields: [list]. Source: [approved record]. Release status: pending verifier approval.' }],
    faqs: [{ question: 'Can support staff confirm employment by email?', answer: 'Only when the authorized verifier and approved process permit it. Otherwise they route the request.' }, { question: 'What fields should be disclosed?', answer: 'Only those the employer’s authorized owner approves for that request.' }, { question: 'What if the requester refuses verification?', answer: 'Keep the request pending or route it; do not release information on trust.' }, { question: 'What evidence should be retained?', answer: 'Requester check, authorization, source, approval, sent version, recipient, and timestamp.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant privacy authority source for controlled disclosure of personal information.' }]
  },
  'philippines-hr-employee-data-export-request': {
    directAnswer: ['An employee data export request needs a declared scope, identity check, source map, access boundary, review owner, and release record. A Philippines-based coordinator can inventory sources and track the request. The records owner decides what must be included, redacted, withheld, or delivered.', 'Do not treat a database export as a complete response. It may include duplicates, third-party information, internal notes, or fields outside the request. Review and scope come before retrieval and release.'],
    takeaways: ['Verify the requester and clarify the scope.', 'Map sources before extracting data.', 'Keep third-party information in the review queue.', 'Use a restricted working location.', 'Record the final release and unresolved items.'],
    taskRows: [
      { lane: 'Identity', philippinesTeam: 'Capture the request and route identity verification.', owner: 'Confirm requester and lawful scope.', check: 'Identity status is explicit' },
      { lane: 'Source map', philippinesTeam: 'List approved systems and data owners.', owner: 'Set inclusion and review rules.', check: 'Source list has an accountable owner' },
      { lane: 'Review', philippinesTeam: 'Track duplicates, third-party data, and missing sources.', owner: 'Decide redaction and release.', check: 'Review outcome is recorded' },
      { lane: 'Delivery', philippinesTeam: 'Prepare the approved package and record secure delivery.', owner: 'Authorize the final release.', check: 'Delivered package matches approval' }
    ],
    sections: [
      { heading: 'Define what the request means', paragraphs: ['Ask for the person, time range, systems, and format requested. “All my data” may still need clarification about archived records, communications, access logs, or recruiting material.', 'The coordinator can make the scope visible. The records owner decides what the applicable process requires.'] },
      { heading: 'Map sources before extraction', paragraphs: ['List HRIS, payroll, benefits, recruiting, access, case, and approved communication systems that may contain relevant records. Name each data owner and expected response.', 'Do not export everything just because it is technically easy. Broad extraction increases review work and the chance of releasing another person’s information.'] },
      { heading: 'Protect mixed records', paragraphs: ['A record may include a manager’s note, another employee’s details, or confidential case material. Flag mixed content for the authorized reviewer instead of copying it into a shared folder.', 'Use a restricted working location, named access, and a delivery method approved for sensitive information.'] },
      { heading: 'Track gaps and decisions', paragraphs: ['The export log should show requested source, response, duplicate status, review decision, and unresolved question. A missing system is not the same as an empty result.', 'Keep the requestor-facing explanation approved. Do not promise that every technical field will appear in a particular format.'] },
      { heading: 'Close with release evidence', paragraphs: ['The final record identifies the approved scope, package version, reviewer, delivery time, and any excluded or pending item. The coordinator records the handoff; the records owner confirms the release.', 'Review the process after completion for sources that repeatedly miss deadlines or produce unclear exports.'] }
    ],
    scripts: [{ label: 'Scope clarification', text: 'Please confirm the time range and systems covered by your request. The records owner will review the final scope before delivery.' }, { label: 'Mixed data flag', text: 'Source [system] contains records that may include other people’s information. It is held for restricted review and is not yet included in the package.' }],
    faqs: [{ question: 'Can a coordinator export all HRIS fields?', answer: 'They can inventory approved sources. The records owner decides scope and release.' }, { question: 'What if a source is missing?', answer: 'Record it as a source response or gap and route it to the data owner.' }, { question: 'Can third-party data be included?', answer: 'Only after authorized review and any required redaction or exclusion decision.' }, { question: 'What proves completion?', answer: 'An approved scope, reviewed package, secure delivery, and retained release record.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant privacy source for access requests, purpose, minimization, and protection of personal data.' }]
  },
  'philippines-recruiting-requisition-approval-packet': {
    directAnswer: ['A requisition approval packet helps leaders decide whether a role is ready to open. A Philippines-based recruiting coordinator can assemble the approved role brief, reporting line, hiring steps, budget authority, and target timing. Leaders retain approval, workforce, compensation, and selection decisions.', 'The packet should make missing approval visible rather than filling gaps with a plausible title or budget. The coordinator prepares evidence and routes questions to the accountable owner.'],
    takeaways: ['Use one approved role brief as the source.', 'Show budget authority and open questions.', 'Separate preparation from approval.', 'Keep hiring criteria consistent with the approved role.', 'Freeze the packet version before publishing the requisition.'],
    taskRows: [
      { lane: 'Role brief', philippinesTeam: 'Assemble approved responsibilities, reporting line, and location details.', owner: 'Approve role need and scope.', check: 'Source owner is named' },
      { lane: 'Approval map', philippinesTeam: 'List required approvers and status.', owner: 'Approve headcount, budget, and terms.', check: 'No missing approval is implied complete' },
      { lane: 'Hiring plan', philippinesTeam: 'Record approved stages, panel, and timing.', owner: 'Approve selection process and exceptions.', check: 'Stage owner is visible' },
      { lane: 'Release', philippinesTeam: 'Prepare the approved requisition and record version.', owner: 'Authorize publication.', check: 'Published copy matches approval' }
    ],
    sections: [
      { heading: 'Start from the approved need', paragraphs: ['A packet should answer why the role exists, what work it covers, who owns it, and what approval remains. Use the manager’s approved brief rather than assembling a role from old requisitions.', 'If the title, reporting line, or scope conflicts across sources, flag the conflict before a requisition is opened.'] },
      { heading: 'Make financial approval visible', paragraphs: ['Record the budget owner and approval status without publishing internal compensation details in public copy. A coordinator can track that an approval is missing, but should not invent a range or assume an earlier role’s approval applies.', 'Questions about compensation, classification, or worker status go to the authorized owner.'] },
      { heading: 'Protect the selection process', paragraphs: ['The packet can list approved stages, interviewers, scorecards, and decision owners. It should not add criteria that were not approved or advise interviewers how to judge a candidate.', 'Recruiting owners decide how to handle a change in stage, panel, or candidate accommodation.'] },
      { heading: 'Version before release', paragraphs: ['Freeze the role brief, approval record, and requisition copy as a matched set. Track who approved the final version and when it may be published.', 'If a leader changes the role after approval, return the packet to the relevant owner. Do not silently update a live requisition from a chat message.'] },
      { heading: 'Review rejected packets', paragraphs: ['A rejected or paused requisition is still useful evidence. Record the missing decision or conflicting source without treating it as a failed candidate or a staffing conclusion.', 'Use recurring gaps to improve the packet checklist, not to widen the coordinator’s approval authority.'] }
    ],
    scripts: [{ label: 'Approval request', text: 'The requisition packet is ready for review. Open items: [list]. Publication remains pending approval from [owner].' }, { label: 'Conflict note', text: 'The role brief and [source] disagree on [field]. I have paused release and routed the question to [owner].' }],
    faqs: [{ question: 'Can a coordinator approve a requisition?', answer: 'No. They assemble and track the packet. Authorized leaders approve the role.' }, { question: 'What if the budget is not stated?', answer: 'Mark it missing and route it to the budget owner.' }, { question: 'Can the coordinator change an interview stage?', answer: 'Only when the change is approved by the recruiting owner.' }, { question: 'When can the job publish?', answer: 'After the required approvals and final copy are matched and authorized.' }],
    sources: [{ name: 'Department of Labor and Employment Philippines: Labor standards', url: 'https://www.dole.gov.ph/labor-standards/', note: 'Named Philippine labour authority source for routing employment-structure questions to responsible owners.' }]
  },
  'philippines-recruiting-candidate-profile-duplicate-review': {
    directAnswer: ['A possible duplicate candidate review compares evidence without merging, deleting, or choosing an authoritative profile by guess. A Philippines-based coordinator can flag matching identifiers, preserve both records, and route the comparison to the recruiting system owner. Recruiters decide which profile to use and how candidate communication should proceed.', 'Use a comparison record that shows matching fields, conflicts, source dates, pipeline stage, consent or communication history, and open questions. A similar name is a reason to review, not proof of identity.'],
    takeaways: ['Flag candidates for review instead of merging automatically.', 'Compare evidence from approved sources.', 'Preserve both profile histories.', 'Keep candidate communication with recruiting owners.', 'Record the merge or no-merge decision and reason.'],
    taskRows: [
      { lane: 'Flag', philippinesTeam: 'Record the possible match and source fields.', owner: 'Decide whether the profiles refer to one person.', check: 'Flag is not a merge' },
      { lane: 'Compare', philippinesTeam: 'List matching and conflicting evidence.', owner: 'Review identity and consent context.', check: 'Sources and dates are visible' },
      { lane: 'Pipeline', philippinesTeam: 'Show stages and scheduled actions on both records.', owner: 'Choose the active recruiting path.', check: 'No candidate loses a scheduled step' },
      { lane: 'Resolution', philippinesTeam: 'Record the authorized merge, link, or no-match outcome.', owner: 'Approve system change and message.', check: 'History remains recoverable' }
    ],
    sections: [
      { heading: 'Treat similarity as a signal', paragraphs: ['Names, phone numbers, email domains, schools, or employers can match by coincidence. Start with a flag and a comparison, not an automatic merge.', 'Record the source and date of each matching field. A current email can carry more weight than an old resume, but the recruiting owner decides what the evidence means.'] },
      { heading: 'Preserve candidate history', paragraphs: ['Keep both profiles, stage histories, messages, interview notes, and consent records available to the authorized reviewer until the system owner decides. A merge can lose context or attach one candidate’s communication to another.', 'The coordinator should not move a candidate to a new stage while identity remains unresolved.'] },
      { heading: 'Coordinate without exposing the review', paragraphs: ['Use a restricted comparison task. Do not ask a candidate to explain an internal duplicate flag through an unapproved message or expose the profile of another person.', 'If a scheduled interview or assessment is affected, the recruiter decides the candidate-safe communication.'] },
      { heading: 'Document the resolution', paragraphs: ['A final record should say merge, link, or no match; who approved it; what evidence was considered; and what system changes followed. Keep the reason factual and avoid speculation about the candidate.', 'If a record is corrected, retain the system’s audit history where available.'] },
      { heading: 'Check the cause, not just the symptom', paragraphs: ['Review whether duplicates come from imports, inconsistent email capture, recruiter handoffs, or candidate self-service. A data-quality owner can fix the source rule.', 'Do not solve recurring duplicates by giving coordination staff permission to merge without review.'] }
    ],
    scripts: [{ label: 'Review flag', text: 'Possible duplicate between profiles [A] and [B]. Matching fields: [list]. Conflicts: [list]. No merge has been made.' }, { label: 'Recruiter escalation', text: 'The duplicate flag may affect [scheduled action]. Please decide the active recruiting path and approved candidate message.' }],
    faqs: [{ question: 'Can a coordinator merge profiles?', answer: 'Only if the system owner has explicitly authorized the reviewed action. A flag alone is not permission.' }, { question: 'What evidence matters?', answer: 'Approved identifiers, source dates, communication history, and pipeline context reviewed by recruiting ownership.' }, { question: 'Should one profile be deleted?', answer: 'The system owner decides retention and merge treatment. Do not delete by assumption.' }, { question: 'What if an interview is scheduled on both?', answer: 'Pause duplicate action and route the conflict to the recruiter so candidate communication stays consistent.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant privacy context for protecting candidate records and limiting unnecessary disclosure.' }]
  },
  'philippines-recruiting-interview-panel-availability': {
    directAnswer: ['Interview-panel coordination works when the required decision makers, priority rules, and candidate communication are explicit. A Philippines-based coordinator can compare calendars, propose approved slots, and flag conflicts. The recruiter or hiring manager decides whether a panel change affects the assessment.', 'Do not fill a gap by replacing a panelist, shortening an interview, or changing the scorecard without approval. A visible conflict is safer than an apparently complete schedule that no longer matches the hiring process.'],
    takeaways: ['List required and optional panel roles.', 'Set time-zone and notice rules.', 'Keep panel changes approved.', 'Protect candidate accessibility and privacy questions.', 'Reconcile calendar, ATS, and scorecard records.'],
    taskRows: [
      { lane: 'Panel map', philippinesTeam: 'Record required roles and approved backups.', owner: 'Decide which roles are essential for the stage.', check: 'Panel rule has an owner' },
      { lane: 'Availability', philippinesTeam: 'Compare calendars and offer compliant slots.', owner: 'Resolve conflicts and exceptions.', check: 'Time zone and format are explicit' },
      { lane: 'Change', philippinesTeam: 'Flag a missing panel role or late conflict.', owner: 'Approve replacement, delay, or process change.', check: 'No silent substitution' },
      { lane: 'Reconcile', philippinesTeam: 'Check invite, ATS stage, and scorecard assignment.', owner: 'Confirm assessment remains valid.', check: 'Required evidence has a reviewer' }
    ],
    sections: [
      { heading: 'Define panel roles before opening slots', paragraphs: ['List who must attend, who may substitute, and what each person contributes. The coordinator can use this map to identify viable slots without deciding whether a role is optional.', 'If the role brief and scorecard disagree with the panel map, stop and route the source conflict.'] },
      { heading: 'Apply a consistent priority rule', paragraphs: ['When calendars collide, the rule might protect a candidate commitment, a required interviewer, or a final-stage deadline. The recruiter approves the rule and handles exceptions.', 'A coordinator should present the conflict and available choices, not decide that one person’s calendar matters more.'] },
      { heading: 'Keep the candidate’s experience accurate', paragraphs: ['Send one approved invitation with time zone, format, participants when permitted, and contact route. Do not promise that a panelist is confirmed if the owner has not confirmed them.', 'Accessibility or accommodation requests go to the qualified recruiting or HR owner.'] },
      { heading: 'Reconcile assessment evidence', paragraphs: ['After scheduling, compare the invite with the ATS stage, panel assignment, scorecard, and approved interview format. A calendar event alone does not prove the right panel is assessing the candidate.', 'Record late changes and their owner. Preserve the original plan where the system supports it.'] },
      { heading: 'Use a conflict drill', paragraphs: ['Test a required interviewer absence, an international time-zone conflict, a candidate change request, and a last-minute panel substitution. Each scenario should name the stop point and approver.', 'Review the drill with the recruiter before using it for live hiring.'] }
    ],
    scripts: [{ label: 'Conflict note', text: 'Required panel role [role] is unavailable for [slot]. Approved alternatives: [list]. Recruiter decision is needed before the candidate is moved.' }, { label: 'Candidate invitation', text: 'Your interview is scheduled for [date/time/time zone] with [approved description]. Please contact [route] if you need an adjustment.' }],
    faqs: [{ question: 'Can the coordinator choose a backup interviewer?', answer: 'Only from an approved backup map. The recruiter handles an unlisted substitute.' }, { question: 'What if the panel cannot meet the deadline?', answer: 'Record the options and route the scheduling decision to recruiting ownership.' }, { question: 'Can a coordinator change the scorecard?', answer: 'No. The hiring owner approves assessment changes.' }, { question: 'What proves panel readiness?', answer: 'Confirmed participants, matching calendar and ATS records, and assigned approved scorecards.' }],
    sources: [{ name: 'U.S. Equal Employment Opportunity Commission: Pre-employment inquiries', url: 'https://www.eeoc.gov/pre-employment-inquiries-and-interviews', note: 'Named interview guidance supporting a clear separation between scheduling and hiring judgment.' }]
  },
  'philippines-hris-effective-date-change-queue': {
    directAnswer: ['An HRIS effective-date queue must distinguish when a change was requested, approved, entered, and meant to take effect. A Philippines-based coordinator can track those dates, route the change to the system owner, and reconcile downstream acknowledgements. The owner decides the effective date and whether a correction is valid.', 'Use separate fields and a source for each date. A saved HRIS field is not proof that payroll, benefits, access, or a manager received the change.'],
    takeaways: ['Name the source for requested and effective dates.', 'Separate approval, entry, and effect.', 'Track downstream acknowledgements.', 'Preserve corrections and prior values.', 'Escalate retroactive or conflicting changes.'],
    taskRows: [
      { lane: 'Request', philippinesTeam: 'Record requested field, date, source, and requester.', owner: 'Approve the change and effective date.', check: 'Request is not treated as approved' },
      { lane: 'Entry', philippinesTeam: 'Track authorized system entry and timestamp.', owner: 'Confirm entry is correct.', check: 'Entry evidence is retained' },
      { lane: 'Downstream', philippinesTeam: 'List payroll, benefits, access, or manager acknowledgements.', owner: 'Resolve conflicts and impact.', check: 'Each dependency has an owner' },
      { lane: 'Reconciliation', philippinesTeam: 'Compare effective record with source and acknowledgements.', owner: 'Approve correction or exception.', check: 'Retroactive change has explicit review' }
    ],
    sections: [
      { heading: 'Use four dates when the work needs them', paragraphs: ['Requested date tells you when someone asked. Approval date tells you when an owner decided. Entry date tells you when a system was changed. Effective date tells you when the change should apply.', 'Combining these into one “updated” field hides the difference between a late entry and a late decision.'] },
      { heading: 'Map the downstream effect', paragraphs: ['A manager change may affect access, reporting lines, payroll, benefits, schedules, and notifications. List those systems from the approved change type, then let each owner confirm the result.', 'Do not assume that an HRIS update automatically propagated. The queue should show acknowledgement or an explicit exception.'] },
      { heading: 'Handle retroactive changes carefully', paragraphs: ['A request that reaches the queue after its proposed effective date can affect prior pay, leave, access, or reporting. Record the timing and route it to the qualified owner.', 'The coordinator should not backdate a field to make the queue look current.'] },
      { heading: 'Preserve corrections', paragraphs: ['Keep the original source, approval, entered value, correction request, and final disposition. A correction log explains why the current field differs from an earlier entry.', 'Restrict employee data and change reasons to approved viewers.'] },
      { heading: 'Audit the queue by date type', paragraphs: ['Sample changes where request, entry, and effective dates differ. Check whether the owner and downstream systems understood the difference.', 'Repeated confusion is a field-design problem. Add definitions and source links rather than asking staff to rely on memory.'] }
    ],
    scripts: [{ label: 'Date clarification', text: 'The request date is [date], proposed effective date is [date], and approval is pending from [owner]. No effective change has been confirmed.' }, { label: 'Reconciliation note', text: 'Entered at [time] by [owner]. Downstream acknowledgements: [list]. Outstanding: [item/owner].' }],
    faqs: [{ question: 'Is an HRIS save an effective change?', answer: 'Not necessarily. The authorized owner must confirm the effective date and downstream impact.' }, { question: 'Who approves a retroactive change?', answer: 'The responsible HR, payroll, or system owner under the approved process.' }, { question: 'What dates belong in the queue?', answer: 'Requested, approved, entered, and effective dates when they differ materially.' }, { question: 'How should a correction be recorded?', answer: 'Keep the original and correction source, approval, timestamps, and final disposition.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant source for controlled access and traceability of employee data changes.' }]
  },
  'philippines-hr-new-hire-equipment-request-routing': {
    directAnswer: ['New-hire equipment routing coordinates an approved request across HR, IT, the manager, and sometimes facilities. A Philippines-based coordinator can track the dependency chain, confirm delivery details, and flag a missed owner. IT and management decide the equipment, access, security, and exceptions.', 'A good request names the hire, approved start date, role needs, asset owner, delivery location, and due points. It should not promise a device or ask HR support to choose a technical configuration.'],
    takeaways: ['Start from the approved role and start-date record.', 'Assign each equipment dependency to its owner.', 'Keep address and device details restricted.', 'Track shipped, received, and configured separately.', 'Escalate unavailable or changed requirements.'],
    taskRows: [
      { lane: 'Request', philippinesTeam: 'Record approved role, start date, location, and required items.', owner: 'Approve need and configuration.', check: 'Source and owner are named' },
      { lane: 'Procurement', philippinesTeam: 'Track approved order or inventory status.', owner: 'Approve purchase, substitute, or delay.', check: 'No substitute is assumed approved' },
      { lane: 'Delivery', philippinesTeam: 'Record shipping or handoff evidence.', owner: 'Confirm custody and security setup.', check: 'Received is distinct from configured' },
      { lane: 'Closeout', philippinesTeam: 'Reconcile equipment, access, and onboarding checklist.', owner: 'Confirm readiness or exception plan.', check: 'Open dependency has an owner' }
    ],
    sections: [
      { heading: 'Tie the request to an approved start', paragraphs: ['Use the approved role and start-date record to establish what is needed and when. Do not order from a casual request that has not been confirmed by the manager or IT owner.', 'If the start date changes, pause or re-sequence the equipment dependencies rather than leaving an obsolete delivery in motion.'] },
      { heading: 'Make the dependency chain explicit', paragraphs: ['Procurement, inventory, imaging, account setup, shipping, receipt, and manager handoff can belong to different owners. List each step and its source of truth.', 'The coordinator tracks the chain and flags a blocked step. They should not choose a technical substitute or bypass a security check.'] },
      { heading: 'Protect delivery information', paragraphs: ['Addresses, phone numbers, asset identifiers, and device details should remain in approved restricted systems. Use a task ID in broad status reporting.', 'Record delivery proof without copying unnecessary personal information into reminders or chat.'] },
      { heading: 'Separate received from ready', paragraphs: ['A package arriving does not prove that the device is configured, encrypted, assigned, or connected to the right account. Track those states separately with the responsible owner.', 'If a device is unavailable, the manager and IT owner decide whether work can start another way. HR support should report the constraint, not promise a solution.'] },
      { heading: 'Reconcile on the first day', paragraphs: ['Check the equipment record, access request, onboarding checklist, and manager confirmation. Note what is ready and what remains open.', 'Review repeated delays by dependency. Fix the handoff map before expanding the coordinator’s access.'] }
    ],
    scripts: [{ label: 'Blocked dependency', text: 'The approved start date is [date]. Equipment step [step] is blocked by [owner/item]. HR and IT decision is still required.' }, { label: 'Delivery note', text: 'Asset [ID] marked received at [time] by [owner]. Configuration and access status remain [status].' }],
    faqs: [{ question: 'Can HR support choose a laptop or software?', answer: 'No. IT and the approved role owner decide configuration and substitutes.' }, { question: 'What if the start date changes?', answer: 'Record the new approved date and ask each dependency owner to confirm the next action.' }, { question: 'What proves readiness?', answer: 'Receipt, configuration, access, and manager confirmation, each with the responsible owner.' }, { question: 'Where should addresses be stored?', answer: 'In the approved restricted system, not broad status notes.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant privacy context for personal delivery and device-assignment information.' }]
  },
  'philippines-hr-employee-language-support-routing': {
    directAnswer: ['Language-support routing should preserve the employee’s original meaning and connect the request to a qualified reviewer or interpreter. A Philippines-based coordinator can record the requested language, preferred channel, source message, and delivery status. They should not rewrite a sensitive message or make an employment answer easier by changing its meaning.', 'Keep the original and translated versions linked, mark who reviewed the translation, and route policy, pay, medical, complaint, and legal questions to the responsible HR owner.'],
    takeaways: ['Keep the source message intact.', 'Record language and channel needs, not assumptions.', 'Use a qualified reviewer for sensitive content.', 'Do not translate an answer that has not been approved.', 'Track delivery and meaning review separately.'],
    taskRows: [
      { lane: 'Request', philippinesTeam: 'Record original message, requested language, and preferred channel.', owner: 'Set urgency and qualified review route.', check: 'Source is retained' },
      { lane: 'Translation', philippinesTeam: 'Coordinate an approved translation or interpreter.', owner: 'Review meaning and sensitive terminology.', check: 'Reviewer is named' },
      { lane: 'Response', philippinesTeam: 'Deliver approved content and record the version.', owner: 'Approve the substantive answer.', check: 'Translation is not the decision' },
      { lane: 'Follow-up', philippinesTeam: 'Track whether the employee received the message.', owner: 'Handle questions or disagreement.', check: 'Receipt is not treated as agreement' }
    ],
    sections: [
      { heading: 'Keep the source beside the translation', paragraphs: ['A translation can lose a qualifier, deadline, or question. Preserve the employee’s original message and link the translated version to it in the approved system.', 'The coordinator may identify the requested language and arrange support. They should not summarize away a detail because it seems repetitive or difficult to translate.'] },
      { heading: 'Match reviewer skill to the topic', paragraphs: ['Routine logistics may use approved language support. A complaint, medical matter, pay question, policy exception, or legal issue needs the qualified owner and a reviewer who can preserve its meaning.', 'Do not let language support become a reason to answer outside the coordinator’s authority.'] },
      { heading: 'Approve the response before translation', paragraphs: ['The responsible HR owner should settle the meaning and decision in the source language before a response is translated. Otherwise the translator may accidentally make a policy choice.', 'Record the approved source response, translator or reviewer, translated version, and delivery channel.'] },
      { heading: 'Handle disagreement as a new route', paragraphs: ['If the employee says the translation is inaccurate, preserve that feedback and route it to the owner. Do not argue about wording or edit the message without review.', 'A receipt confirms delivery, not that the employee understood or agreed.'] },
      { heading: 'Test meaning with concrete examples', paragraphs: ['Review a scheduling notice, a benefits question, and a sensitive complaint with qualified language support. Check dates, names, modal words, and stop points.', 'Use the test to improve approved language resources, never to replace topic expertise.'] }
    ],
    scripts: [{ label: 'Language intake', text: 'I have preserved your original message and routed it for [language] support. HR will review the answer before it is sent.' }, { label: 'Meaning concern', text: 'The recipient has raised a translation concern. The original and translated versions are held for qualified review.' }],
    faqs: [{ question: 'Can the coordinator translate a termination or complaint message?', answer: 'Only under an approved process with qualified review. Sensitive decisions and meaning remain with the HR owner.' }, { question: 'Should the original be replaced?', answer: 'No. Preserve it and link the reviewed translation.' }, { question: 'Does receipt mean agreement?', answer: 'No. Record delivery separately from understanding or consent.' }, { question: 'What if no reviewer is available?', answer: 'Keep the request pending or use the approved backup route. Do not improvise a substantive answer.' }],
    sources: [{ name: 'Official Gazette of the Republic of the Philippines: 1987 Constitution', url: 'https://www.officialgazette.gov.ph/constitutions/1987-constitution/', note: 'Named Philippine public source for the national context of language access and communication.' }]
  },
  'philippines-hr-open-case-handoff-register': {
    directAnswer: ['An open-case handoff register shows who owns unfinished HR work, what happens next, and where approved evidence lives. A Philippines-based coordinator can maintain the status, next action, due date, and owner. They should not copy sensitive narratives into the register or decide the case outcome.', 'Keep the register small enough to be useful: case ID, category, owner, status, next action, due date, last update, and restricted evidence location. The case owner remains responsible for substantive judgment.'],
    takeaways: ['Use a case ID instead of a narrative.', 'Give every item one next action and one owner.', 'Separate waiting from closed.', 'Keep sensitive evidence in the approved case system.', 'Reconcile stale entries with the case owner.'],
    taskRows: [
      { lane: 'Open item', philippinesTeam: 'Create a minimal record from the approved case source.', owner: 'Confirm case owner and scope.', check: 'Register has no unnecessary narrative' },
      { lane: 'Next action', philippinesTeam: 'Record the approved next step, due date, and dependency.', owner: 'Choose substantive action.', check: 'Next action is actionable' },
      { lane: 'Handoff', philippinesTeam: 'Notify the new owner and track acknowledgement.', owner: 'Accept responsibility and review detail.', check: 'Owner change is explicit' },
      { lane: 'Stale review', philippinesTeam: 'Flag no-update items and request owner status.', owner: 'Update or close the case.', check: 'Closed status has owner confirmation' }
    ],
    sections: [
      { heading: 'Make ownership visible without retelling the case', paragraphs: ['The register is an operating view, not the case file. Use a case ID, category, current owner, next action, due date, and link to the approved restricted evidence.', 'A short status such as “waiting for HR review” is safer and more useful than a paragraph about the employee’s complaint or medical situation.'] },
      { heading: 'Write one next action', paragraphs: ['“Follow up” is too vague. “HR owner reviews the approved attendance record by Friday” tells the owner what is expected while keeping the decision with HR.', 'If more than one action is needed, either assign separate owners or state the dependency. Do not make one coordinator the owner of work they cannot decide.'] },
      { heading: 'Handle handoffs as an event', paragraphs: ['When ownership changes, record the prior owner, new owner, time, reason supplied, and acknowledgement. The new owner should receive access through the approved case system, not through an exported narrative.', 'A calendar invite or message is not enough if the case system still names the old owner.'] },
      { heading: 'Find stale cases safely', paragraphs: ['Sort by last update and due date, then ask the named owner for status. Do not close a case because it is old or because a reminder was sent.', 'Sensitive cases may need a restricted stale-review route. Keep their existence and status visible only to the permitted group.'] },
      { heading: 'Close with evidence', paragraphs: ['The case owner confirms the disposition and approved archive location. The coordinator records that confirmation and removes or narrows access when instructed.', 'Review recurring stale items by owner, dependency, or intake quality. A register reveals coordination gaps; it does not solve substantive cases.'] }
    ],
    scripts: [{ label: 'Handoff note', text: 'Case [ID] is moving from [old owner] to [new owner]. Next action: [action]. Due: [date]. Restricted evidence remains at [approved location].' }, { label: 'Stale review', text: 'Case [ID] has no recorded update since [date]. Please confirm status, next action, or the approved closeout.' }],
    faqs: [{ question: 'Should the register contain the case story?', answer: 'No. Keep it to routing metadata and the approved restricted evidence location.' }, { question: 'Can a coordinator close a case?', answer: 'Only after the authorized owner confirms disposition and instructs closeout.' }, { question: 'What if two people need to act?', answer: 'Name the accountable owner and record the dependency or separate tasks.' }, { question: 'How should a stale sensitive case be reviewed?', answer: 'Use the permitted restricted owner group and avoid broad reminders that reveal the matter.' }],
    sources: [{ name: 'National Privacy Commission of the Philippines: Data Privacy Act', url: 'https://privacy.gov.ph/data-privacy-act/', note: 'Relevant privacy source for minimizing detail and controlling access in case registers.' }]
  }
};
